export interface Product {
  id: string;
  name: string;
  description: string;
  price: number;
  stock: number;
  category: string;
  image_url: string;
  featured: boolean;
  created_at?: string;
}

export interface CartItem extends Product {
  quantity: number;
}

export interface Order {
  id: string;
  customer_name: string;
  total: number;
  status: 'pending' | 'paid' | 'shipped' | 'delivered';
  created_at: string;
  items: CartItem[];
}

export interface SalesData {
  name: string;
  sales: number;
  revenue: number;
}

export interface DbConfig {
  url: string;
  key: string;
}

export enum Page {
  STORE = 'STORE',
  ADMIN_DASHBOARD = 'ADMIN_DASHBOARD',
  ADMIN_PRODUCTS = 'ADMIN_PRODUCTS',
  ADMIN_SETTINGS = 'ADMIN_SETTINGS',
  CART = 'CART',
  CHECKOUT = 'CHECKOUT'
}

import { createClient, SupabaseClient } from '@supabase/supabase-js';
import { Product, Order, DbConfig } from '../types';

let supabase: SupabaseClient | null = null;

export const initSupabase = (config: DbConfig) => {
  if (config.url && config.key) {
    try {
      supabase = createClient(config.url, config.key);
      return true;
    } catch (e) {
      console.error("Supabase init error:", e);
      return false;
    }
  }
  return false;
};

export const checkConnection = async (): Promise<boolean> => {
  if (!supabase) return false;
  try {
    const { count, error } = await supabase.from('products').select('*', { count: 'exact', head: true });
    if (error) throw error;
    return true;
  } catch (e) {
    console.error("Connection check failed:", e);
    return false;
  }
};

export const fetchProducts = async (): Promise<Product[]> => {
  if (!supabase) return [];
  const { data, error } = await supabase.from('products').select('*').order('created_at', { ascending: false });
  if (error) {
    console.error("Fetch products error:", error);
    return [];
  }
  return data as Product[];
};

export const createProduct = async (product: Omit<Product, 'id'>): Promise<Product | null> => {
  if (!supabase) return null;
  const { data, error } = await supabase.from('products').insert([product]).select().single();
  if (error) {
    console.error("Create product error:", error);
    return null;
  }
  return data as Product;
};

export const updateProduct = async (id: string, updates: Partial<Product>): Promise<boolean> => {
  if (!supabase) return false;
  const { error } = await supabase.from('products').update(updates).eq('id', id);
  if (error) {
    console.error("Update product error:", error);
    return false;
  }
  return true;
};

export const deleteProduct = async (id: string): Promise<boolean> => {
  if (!supabase) return false;
  const { error } = await supabase.from('products').delete().eq('id', id);
  if (error) return false;
  return true;
};

export const createOrder = async (order: Omit<Order, 'id' | 'created_at'>): Promise<boolean> => {
  if (!supabase) return false;
  const { error } = await supabase.from('orders').insert([{
    customer_name: order.customer_name,
    total: order.total,
    status: order.status,
    items: order.items
  }]);

  if (error) {
    console.error("Create order error:", error);
    return false;
  }
  return true;
};

export const fetchOrders = async (): Promise<Order[]> => {
  if (!supabase) return [];
  const { data, error } = await supabase.from('orders').select('*').order('created_at', { ascending: false });
  if (error) return [];
  return data as Order[];
};

import { GoogleGenAI } from "@google/genai";

export const generateProductDescription = async (productName: string, category: string): Promise<string> => {
  // NOTE: Ideally, the API key should come from a secure backend or user input.
  // For this demo, we assume the user has set it in the environment or we prompt for it.
  // We will access it from process.env if available, or rely on the UI to provide it.

  const apiKey = process.env.API_KEY || localStorage.getItem('GEMINI_API_KEY');

  if (!apiKey) {
    throw new Error("Gemini API Key não encontrada. Configure-a nas configurações.");
  }

  const ai = new GoogleGenAI({ apiKey });

  try {
    const prompt = `Crie uma descrição atraente, criativa e vendedora para um produto de papelaria.
    Nome do produto: ${productName}
    Categoria: ${category}

    A descrição deve ter cerca de 2 parágrafos curtos. Use um tom encantador e organizado.`;

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-latest',
      contents: prompt,
    });

    return response.text || "Não foi possível gerar a descrição.";
  } catch (error) {
    console.error("Gemini AI Error:", error);
    throw new Error("Falha ao conectar com a IA.");
  }
};

import React, { useState, useEffect } from 'react';
