        </div>

        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Google Gemini API Key</label>
          <div className="flex gap-2">
             <input
              type="password"
              value={apiKey}
              onChange={(e) => setApiKey(e.target.value)}
