                                onChange={(e) => setImageUrlInput(e.target.value)}
                             />
                             <button type="button" onClick={handleAddImageUrl} className="bg-gray-100 hover:bg-gray-200 px-4 rounded-lg font-bold text-gray-600">+</button>
